before.lib/ledger.ex:
defmodule Ledger do
  @moduledoc "Internal application ledger. Callers use start_link, record and total; representation is private."
  def start_link, do: Agent.start_link(fn -> %{entries: []} end)
  def record(pid, n), do: Agent.update(pid, &%{entries: [n | &1.entries]})
  def total(pid), do: Agent.get(pid, &Enum.sum(&1.entries))
end

